/**
 * Customer reviews as cards or plain entries: rating, title, text, author and date. Axes: layout (list, grid),
 * columns, item (card, plain), avatar (none, image), tone, density.
 */
import { For, type JSX } from "solid-js";
import { Grid, Group, Stack, Text, Title } from "../compose";
import { ArticleBlock } from "../components/article-block";
import { EmptyState } from "../components/empty-state";
import { MediaFrame } from "../components/media-frame";
import { Rating } from "../components/rating";
import { SectionFrame } from "../components/section-frame";
import { cn, tpl } from "../utils";
import type { Review, ReviewLabels } from "./review-list.types";

export type ReviewListProps = {
  id: string;
  title: string;
  reviews: Review[];
  labels: ReviewLabels;
  layout?: "list" | "grid";
  item?: "card" | "plain";
  avatar?: "none" | "image";
  tone?: "default" | "muted";
  density?: "default" | "roomy";
  landmarkLabel?: string;
};

export function ReviewList({
  id,
  title,
  reviews,
  labels,
  layout = "list",
  item = "card",
  avatar = "none",
  tone = "default",
  density = "default",
  landmarkLabel,
}: ReviewListProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      tone={tone}
      density={density}
      measure={(((layout as string) === "list") ? "2xl" : "default")}
      landmarkLabel={landmarkLabel}
    >
      {((reviews?.length ?? 0) === 0) ? (
        <EmptyState icon="message-square-quote" title={labels.empty} />
      ) : null}
      <Grid cols={(((layout as string) === "grid") ? "1-3" : "1")} class="gap-4" data-testid="items">
        <For each={reviews ?? []}>{(r) => (
          <ArticleBlock
            class={cn(
              "flex h-full flex-col gap-4",
              (
                (item as string) === "card" ? "rounded bg-card p-6 inset-ring inset-ring-border"
                : "border-b border-border pb-4"
              )
            )}
            testid="item"
          >
            <Rating value={r.rating} label={tpl(labels.ratingLabel, r.rating)} />
            <Title as={3} size="base" weight="bold">
              {r.title}
            </Title>
            <Text size="sm" class="text-muted-foreground">
              {r.text}
            </Text>
            <Group gap="4" align="center" class="mt-auto">
              {((avatar as string) === "image") ? (
                <MediaFrame alt={r.author} ratio="1/1" class="size-10 shrink-0 rounded-full" />
              ) : null}
              <Stack gap="0">
                <Text size="sm" weight="semibold">
                  {r.author}
                </Text>
                <Text size="xs" class="text-muted-foreground">
                  {r.date}
                </Text>
              </Stack>
            </Group>
          </ArticleBlock>
        )}</For>
      </Grid>
    </SectionFrame>
  );
}

